import requests
from .yaft import Yaft
from .sshtools import SSHTools

requests.packages.urllib3.disable_warnings()
try:
    from robotide.lib.robot.api import logger
except ImportError:
    from robot.api import logger


class hran_compa(object):
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    def __init__(self):
        self.ssh_tools = None
        self.working_module_status = {
            "operationalState": "enabled",
            "availabilityStatus": "online",
            "proceduralStatus": "configured",
        }
        self.non_working_module_status = {
            "operationalState": "disabled",
            "availabilityStatus": "offline",
            "proceduralStatus": "notInitialized",
        }
        self.ssh_user = None
        self.ssh_password = None

    def setup_hran_compa(self, ssh_user, ssh_password):
        """
        Hran COMPA setup

        | **Author:** jaroslaw.piszczala@nokia.com
        | **Maintainer:** jaroslaw.piszczala@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------+------+--------------------------------------+
        | Parameter name   | Man. | Description                          |
        +==================+======+======================================+
        | ssh_user         | yes  | Login for ssh connection with BTS    |
        +------------------+------+--------------------------------------+
        | ssh_password     | yes  | Password for ssh connection with BTS |
        +------------------+------+--------------------------------------+

        """
        self.ssh_tools = SSHTools(ssh_user, ssh_password)

    def check_if_ssh_is_enabled(self, log_info=True):
        """
        Check if SSH is enable, and return status.

        | **Author:** jaroslaw.piszczala@nokia.com
        | **Maintainer:** jaroslaw.piszczala@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------+------+------------------------------------------------------------------+
        | Parameter name   | Man. | Description                                                      |
        +==================+======+==================================================================+
        | ssh_user         | yes  | Login for ssh connection with BTS                                |
        +------------------+------+------------------------------------------------------------------+
        | ssh_password     | yes  | Password for ssh connection with BTS                             |
        +------------------+------+------------------------------------------------------------------+
        | log_info         | no   | Pattern for software, which should be installed. (default: True) |
        +------------------+------+------------------------------------------------------------------+

        **Return Value:**

        True if SSH is enable, False if disable.


        **Example:**

        .. code-block:: robotframework

            ${ssh_status}=  Check if ssh is enabled  ssh_user=${SMOD1['USERNAME']}  ssh_password=${SMOD1['PASSWORD']}

        """
        return self.ssh_tools.check_if_ssh_is_enabled(log_info)

    def enable_ssh_by_trs(self):
        """
        Try to enable SSH connection by Transport.

        | **Author:** jaroslaw.piszczala@nokia.com
        | **Maintainer:** jaroslaw.piszczala@nokia.com
        | **Released with version:** ---

        **Return Value:**

        True if SSH enabled successfully, False if not.

        """
        return self.ssh_tools.enable_ssh_by_trs()

    def install_software_from_directory_using_yaft(
        self,
        software_pattern,
        ssh_user,
        ssh_password,
        msm_ip="192.168.255.129",
        packages_directory="/home/ute/btsauto/TARGET_SW",
        swconfig_path=None,
        log_directory="/home/ute/Autotest",
        sign_dirs=None,
        ignore_fsps=False,
    ):

        """
        Install software, which match given pattern, from given directory by using yaft

        | **Author:** jaroslaw.piszczala@nokia.com
        | **Maintainer:** jaroslaw.piszczala@nokia.com
        | **Released with version:** ---

        | **Full description:**
        |
        | Software patterns:
        | - Newest package for technology ex. FL00
        | - Concrete package ex. SBTS00_FSM3_9999_170208_001857

        **Input Parameters:**

        +--------------------+------+-------------------------------------------------------------------------+
        | Parameter name     | Man. | Description                                                             |
        +====================+======+=========================================================================+
        | software_pattern   | yes  | Pattern for software, which should be installed.                        |
        +--------------------+------+-------------------------------------------------------------------------+
        | ssh_user           | yes  | Login for ssh connection with BTS                                       |
        +--------------------+------+-------------------------------------------------------------------------+
        | ssh_password       | yes  | Password for ssh connection with BTS                                    |
        +--------------------+------+-------------------------------------------------------------------------+
        | msm_ip             | no   | BTS IP (default: 192.168.255.129)                                       |
        +--------------------+------+-------------------------------------------------------------------------+
        | packages_directory | no   | Directory with software packages (default: /home/ute/btsauto/TARGET_SW) |
        +--------------------+------+-------------------------------------------------------------------------+
        | swconfig_path      | no   | Path to swconfig which should be copied to BTS (default: None)          |
        +--------------------+------+-------------------------------------------------------------------------+
        | log_directory      | no   | Path to test log directory  (default: /home/ute/Autotest)               |
        +--------------------+------+-------------------------------------------------------------------------+
        | sign_dirs          | no   | Optional directories with files to sign ex."foo|bar" (default: None)    |
        +--------------------+------+-------------------------------------------------------------------------+

        **Return Value:**

        Return code from YAFT script

        **Example for SBTS16:**

        .. code-block:: robotframework

            Install software from directory using yaft  software_pattern=SBTS16
            ...  ssh_user=${SMOD1['USERNAME']}  ssh_password=${SMOD1['PASSWORD']}

        **Example for FL:**

        .. code-block:: robotframework

            Install software from directory using yaft  software_pattern=FL
            ...  ssh_user=${SMOD1['USERNAME']}  ssh_password=${SMOD1['PASSWORD']}  msm_ip=${SMOD1['TRS_IP']}
            ...  log_directory=${TestFiles}

        """
        yaft = Yaft(
            software_pattern,
            ssh_user,
            ssh_password,
            packages_directory,
            swconfig_path,
            msm_ip,
            log_directory,
            sign_dirs,
            ignore_fsps,
        )
        return yaft.install_software_from_directory_using_yaft()

    @staticmethod
    def get_base_sw_package_name(package_name, package_pattern="SBTS"):
        """
        Return base sw package name downloaded from REST.

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Return base sw package name downloaded from REST.
        | Sw package name returned from REST can consist some misleading prefix.

        **Input Parameters:**

        +------------------+------+-----------------------------------------------------+
        | Parameter name   | Man. | Description                                         |
        +==================+======+=====================================================+
        | package_name     | yes  | Package name got from BTS                           |
        +------------------+------+-----------------------------------------------------+
        | package_pattern  | no   | Pattern looking for in package_name (default: SBTS) |
        +------------------+------+-----------------------------------------------------+

        **Return Value:**

        Package name starts from SBTS*

        **Example:**

        .. code-block:: robotframework

            ${active_sw}=  Get base sw package name  WN16_FL16_GF16_SBTS16.10_ENB_A53_0000_005126_000000

        """
        return package_name[package_name.index(package_pattern):]

    def parse_modules_status(self, *args):
        """
        Return True if all states in dictionaries are equal expected.

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Return True if all states in dictionaries are equal expected
        | (listed in status_dict variable).
        | Dictionaries used in here are created from bim downloaded from
        | SBTS16's uri page by keyword for example
        | "${frm_status}=    REST Read frm status    uri=/mz/p/v1/pbts/1"

        **Input Parameters:**

        +------------------+------+---------------------------------------------------------------------+
        | Parameter name   | Man. | Description                                                         |
        +==================+======+=====================================================================+
        | args             | yes  | List of dictionaries with statuses gathered from bim file in SBTS16 |
        +------------------+------+---------------------------------------------------------------------+

        **Return Value:**

        bool - True if all modules statuses are equal expected, False othewise

        **Example:**

        .. code-block:: robotframework

            ${status_verdict}=    Parse modules status    ${frm_status}    ${fsm_status}

        """
        verdicts = []
        for modules in args:
            verdicts.append(self._are_states_expected(modules, self.working_module_status))
        return all(verdicts)

    def sort_rm_states_by_faultid_23(self, alarms, all_rm_status):
        """
        Return True if all modules states are equal expected.

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Return True if all modules states are equal expected.
        | Modules affected by fauldId 23 has following expected states:
        | {"operationalState": "disabled","availabilityStatus": "offline","proceduralStatus": "notInitialized"}
        |
        | Dictionaries used in here are created from bim downloaded from
        | SBTS16's uri page by keyword, for example:
        | "${frm_status}=    REST Read frm status    uri=/mz/p/v1/pbts/1"

        **Input Parameters:**

        +------------------+------+-------------------------------------------------------------------+
        | Parameter name   | Man. | Description                                                       |
        +==================+======+===================================================================+
        | alarms           | yes  | Alarms gathered from BTS by rest_read_active_alarm_sbts16 keyword |
        +------------------+------+-------------------------------------------------------------------+
        | all_rm_status    | yes  | Radio modules statuses                                            |
        +------------------+------+-------------------------------------------------------------------+

        **Return Value:**

        bool - True if all modules statuses are equal expected, False othewise

        **Example:**

        .. code-block:: robotframework

            ${status_verdict}=    Sort rm states by faultid 23    ${active_alarms}    ${frm_status}

        """
        working_modules = {}
        non_working_modules = {}
        affected_module_list = \
            [self._get_rm_name_from_alarm_description(alarm) for alarm in alarms.values() if alarm["faultId"] == 23]

        for key, value in all_rm_status.items():
            if key in affected_module_list:
                non_working_modules[key] = value
            else:
                working_modules[key] = value
        return self._are_modules_states_as_expected(non_working_modules, working_modules)

    def _are_modules_states_as_expected(self, non_working_modules, working_modules):
        working_module_states = self._are_states_expected(working_modules, self.working_module_status)
        non_working_module_stateus = self._are_states_expected(non_working_modules, self.non_working_module_status)
        return working_module_states and non_working_module_stateus

    @staticmethod
    def _get_rm_name_from_alarm_description(alarm):
        return alarm["Alarm text"].split(": ")[1]

    @staticmethod
    def _are_states_expected(all_rm_status, module_status):
        for flexi in all_rm_status:
            if all_rm_status[flexi] != module_status:
                logger.debug("{} NOK {}".format(flexi, all_rm_status[flexi]))
                return False
            else:
                logger.debug("{} OK {}".format(flexi, all_rm_status[flexi]))
        return True
